import assert from "node:assert/strict";
import { existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { compileEngineVisualStyles } from "./engine-visual-styles.ts";

// Long-Term Memory ships no stylesheet, so every utility class it uses must
// already be generated by the Engine's own stylesheet.
const repoRoot = resolve(dirname(process.argv[1] ?? process.cwd()), "..");
const engineRoot = resolve(process.env.MARINARA_ENGINE_ROOT || join(repoRoot, "../Marinara-Engine"));
const packageClientSource = join(repoRoot, "packages/long-term-memory/src/engine/packages/client/src/**/*.{ts,tsx}");

function classSelectors(css: string) {
  const classes = new Set<string>();
  for (const [, prelude] of css.matchAll(/([^{};]*)\{/gu)) {
    if (prelude!.trim().startsWith("@")) continue;
    for (const [, name] of prelude!.matchAll(/\.((?:\\.|[\w-])+)/gu)) classes.add(name!.replace(/\\(.)/gu, "$1"));
  }
  return classes;
}

async function main() {
  assert.ok(
    existsSync(join(repoRoot, "packages/long-term-memory/src/engine/packages/client/src")),
    "Long-Term Memory client source not found",
  );
  const hostClasses = classSelectors(await compileEngineVisualStyles(engineRoot));
  const packageClasses = classSelectors(await compileEngineVisualStyles(engineRoot, packageClientSource));
  const missing = [...packageClasses].filter((name) => !hostClasses.has(name)).sort();
  assert.deepEqual(
    missing,
    [],
    `${missing.length} Long-Term Memory classes are not served by the Engine stylesheet:\n${missing.join("\n")}`,
  );
  console.log(`Long-Term Memory host styles ok: ${hostClasses.size} host classes, 0 missing`);
}

void main().catch((error) => {
  process.stderr.write(`${error instanceof Error ? (error.stack ?? error.message) : String(error)}\n`);
  process.exitCode = 1;
});
